import{_ as i,l as o,o as e,c as l,v as r,p as s,x as t,d as E,i as h,S as B}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"价值：BM / EP / CF","description":"","frontmatter":{"title":"价值：BM / EP / CF","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/value-factors.md","filePath":"quant/value-factors.md","lastUpdated":1789023840000}'),p={name:"quant/value-factors.md"};function P(c,a,d,M,F,f){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="价值-bm-ep-cf" tabindex="-1">价值：BM / EP / CF <a class="header-anchor" href="#价值-bm-ep-cf" aria-label="Permalink to &quot;价值：BM / EP / CF&quot;">​</a></h1><div class="epigraph"><p>用账面、盈余或现金流去除以价格，得到的是同一类比较：当前市值相对于基本面是否便宜；便宜组在事后平均收益上系统性偏高。</p><footer>—— 综合 Fama–French 的 B/M 与 Lakonishok–Shleifer–Vishny 的相对价值度量</footer></div><p>价值因子不是只有 HML。账面市值比（B/M）、盈余收益率（E/P）、现金流价格比（CF/P 或 C/P）都在问：为每单位基本面付了多少价格。Fama–French 把 B/M 做成<a href="/quant/ff3">三因子</a>里的 HML；Lakonishok、Shleifer、Vishny 1994 年用 E/P、C/P 与销售增长论证「反向投资」。本篇把这三条度量放在同一套排序语言里，写它们何时一致、何时因亏损、应计与无形资产而分道。质量与盈利不是价值，见<a href="/quant/quality-profitability">质量与盈利</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>价格低可能是风险（困境、杠杆、周期底部），也可能是错误定价（外推成长、忽视均值回归）。无论哪一种，都需要一个把「便宜」写成可排序数字的定义。分子是存量还是流量，决定了对亏损公司、高摊销公司、高研发公司的处理。B/M 用资产负债表的账面股权，E/P 用利润表，CF/P 用现金流量表或 EBITDA 一类近似。三者在「便宜成长」与「贵价值」两端大体同向，在中间组和会计异常上会给出相反的十分位。</p><p>若只保留 B/M，互联网、品牌与研发密集型行业会被系统性送进成长组，因为账面股权不含多数无形资产。若只保留 E/P，亏损公司要么被丢弃要么被单独成组，样本选择会改变溢价。价值因子的问题因此首先是<strong>会计映射</strong>，其次才是多空。</p><h3 id="三种比率各自在量什么" tabindex="-1">三种比率各自在量什么 <a class="header-anchor" href="#三种比率各自在量什么" aria-label="Permalink to &quot;三种比率各自在量什么&quot;">​</a></h3><p>B/M \\(= B/M\\)，B 通常是普通股账面股权，M 是普通股市值。它接近资产定价里的「倒过来的托宾 q」，对杠杆与历史留存敏感。E/P 用净利润或扣除非经常项后的盈余；负盈余使比率失去单调解释，实务上常把亏损单独放最贵或最便宜组之一，必须事先声明。CF/P 用经营现金流或自由现金流。经营现金流能减弱应计操纵，自由现金流还扣掉资本开支，于是和<a href="/quant/investment-factor">投资因子</a>部分重叠。</p><p><span class="marginnote">HML 的分母是 12 月底市值，分子是上一年财报账面，再等到次年 6 月才重构。E/P、CF/P 若用「当期价格、最新 TTM」，信息含量和换手都高于 1993 年 HML。Asness–Frazzini 的 HML Devil 就是把 B/M 的价格改成月度更新；那是价值度量的时效，不是新的基本面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>统一的做法是每年（或每月）在可投资宇宙里计算三个比率，用 NYSE 分位做断点，价值加权多空。为避免货币单位问题，全部用比率而不是绝对价格。常见清洗：剔除金融与负账面（B/M 未定义或经济含义翻转）、对 E/P 单独处理亏损、对 CF/P 要求经营现金流可得。交叉规模的 2×3 与 HML 相同，便于与 SMB 并存。</p><p>复合价值可以把分位排名等权平均（B/M、E/P、CF/P、有时加 EV/EBITDA），再按复合排名排序。这能降低单一会计科目的噪声，也会把投资与盈利的信息悄悄引进来——复合因子不再是「纯价值」。报告溢价时必须列出成分与权重。</p> \\[\\mathrm{HML}^{\\mathrm{BM}}=\\tfrac12(R_{S/H}+R_{B/H})-\\tfrac12(R_{S/L}+R_{B/L}) \\]<p>对 E/P、CF/P 只改排序键。相关高时三条腿几乎共线；相关下降的时期（会计制度变化、亏损潮、无形资产扩张）才是它们的增量信息。</p><h3 id="行业中性与企业价值口径" tabindex="-1">行业中性与企业价值口径 <a class="header-anchor" href="#行业中性与企业价值口径" aria-label="Permalink to &quot;行业中性与企业价值口径&quot;">​</a></h3><p>行业间的 B/M 差异很大一部分是商业模式，不是相对便宜。行业内排序（或对行业虚拟回归后再排序）得到的价值更接近「相对同业折价」，溢价通常仍在，β 对行业轮动更稳。企业价值口径用 EV/EBITDA、EV/CF，把净债务放进价格，避免把高现金公司误判为便宜股权。HML 是股权口径；杠杆变化会让 B/M 与 EV 倍数暂时分叉。</p>',16)),(e(),s(B,null,{default:t(()=>[h(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PX%5B%22%E4%BB%B7%E6%A0%BC%20%2F%20%E5%B8%82%E5%80%BC%22%5D%20--%3E%20BM%5B%22B%2FM%20%E8%B4%A6%E9%9D%A2%E5%AD%98%E9%87%8F%22%5D%0A%20%20PX%20--%3E%20EP%5B%22E%2FP%20%E7%9B%88%E4%BD%99%E6%B5%81%E9%87%8F%22%5D%0A%20%20PX%20--%3E%20CF%5B%22CF%2FP%20%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%0A%20%20BM%20--%3E%20SORT%5B%22%E5%88%86%E4%BD%8D%E6%8E%92%E5%BA%8F%20%2F%20%E5%8F%AF%E9%80%89%E8%A1%8C%E4%B8%9A%E4%B8%AD%E6%80%A7%22%5D%0A%20%20EP%20--%3E%20SORT%0A%20%20CF%20--%3E%20SORT%0A%20%20SORT%20--%3E%20LS%5B%22%E4%BB%B7%E5%80%BC%E5%8A%A0%E6%9D%83%E5%A4%9A%E7%A9%BA%22%5D%0A%20%20LS%20--%3E%20DIAG%5B%22%E4%B8%8E%20HML%E3%80%81RMW%E3%80%81CMA%20%E7%9A%84%E7%9B%B8%E5%85%B3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>风险叙事：高 B/M 公司接近账面清算价值，成长期权少，对经济下行与信贷条件更敏感，因此要求溢价。E/P 高可能是盈利处于周期顶、市场已在贴现衰退；也可能是真便宜。CF/P 高类似，但少受应计影响。行为叙事：投资者对过去销售与盈利增长外推过远，低增长、低倍数的股票被冷落，随后均值回归。LSV 1994 强调后一条，Fama–French 强调前一条。截面回归分不开它们：两者都预测「便宜组收益高」。</p><p>无形资产使 B/M 的风险叙事变钝。研发费用化压低账面，真正的成长公司看起来更「成长」，价值组越来越像有形资产密集、资本开支大的公司，于是和 CMA 的相关上升。这是 2015 年后「价值是否失效」讨论的会计背景，而不只是量化资金拥挤。</p><h3 id="亏损、应计与一次性项目" tabindex="-1">亏损、应计与一次性项目 <a class="header-anchor" href="#亏损、应计与一次性项目" aria-label="Permalink to &quot;亏损、应计与一次性项目&quot;">​</a></h3><p>E/P 在亏损潮年份会把大量股票赶出排序或堆进极端组，溢价的时序波动有一部分是样本构成在变。用正向盈余的 E+/P，或用毛利率、营业利润代替净利润，能稳住排序，但已经滑向盈利因子。CF/P 对一次性资产出售敏感；需要连续多年现金流或扣除非经常项。B/M 对库存回写、商誉减值敏感：减值把账面砸低，公司会从价值组掉进成长组——恰好在「更便宜了」的时候被踢出多头。这是会计滞后与因子重构日期必须写进说明书的原因。</p><p><span class="marginnote">价值溢价的容量主要在大盘价值加权腿。等权小盘价值混有微观结构与<a href="/quant/short-term-reversal">反转</a>。国际与 A 股上 E/P、CF/P 有时比 B/M 更稳，因为账面质量与壳资源让 B 的噪声大于 E 与 CF。不要把美股 HML 的失效直接翻译成「价值死了」。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>财务滞后与 6 月重构避免前视，也让价值在价格暴跌后最多延迟半年才加仓——HML Devil 用当期价格就是为了加快。加快的代价是换手与和动量的负相关更尖锐。前视账面（用未公开的年报）会在回测里造出假溢价。</p><p>不要把 EV/EBITDA 的多空叫做 HML。不要在同一回归里同时放 HML、E/P 组合、CF/P 组合还声称三个独立 α——共线性会让 t 值乱跳。应先看相关，再<a href="/quant/factor-orthogonal">正交化</a>。价值与盈利应当分开：<a href="/quant/ff5">五因子</a>的教训是贵而高盈利、便宜而低盈利是不同的腿。</p><p><span class="marginnote">出处分层：B/M 与 HML 见 Fama &amp; French, 1992/1993；E/P、C/P 等反向策略见 Lakonishok, Shleifer &amp; Vishny, Journal of Finance, 1994。HML Devil 见 Asness &amp; Frazzini。不要给「CF 因子」伪造单独的 Fama–French 编号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>价值是价格相对基本面便宜；B/M、E/P、CF/P 是三条会计映射，不是三个无关的风险源。</li><li>亏损处理、行业中性、股权 vs 企业价值口径会改变组合构成与和 CMA 的相关。</li><li>时效（年度账面 vs 月度价格）改变换手，也改变与动量的负相关强度。</li><li>与盈利、投资重叠时要用正交化，而不是并列三个价值腿。</li><li>出处：Fama &amp; French, 1992/1993；LSV, Journal of Finance, 1994。</li></ul>',12))])}const A=i(p,[["render",P]]);export{u as __pageData,A as default};
